// Каталог: цены по возрастанию. Есть ли товар ровно за price?
func hasPrice(_ price: Int, in prices: [Int]) -> Bool {
    var low = 0
    var high = prices.count
    while low < high {
        let mid = low + (high - low) / 2
        if prices[mid] == price { return true }
        if prices[mid] < price {
            low = mid + 1
        } else {
            high = mid
        }
    }
    return false
}
