func indexOf(_ target: Int, in sorted: [Int]) -> Int? {
    var low = 0
    var high = sorted.count
    while low < high {
        let mid = low + (high - low) / 2
        if sorted[mid] == target { return mid }
        if sorted[mid] < target {
            low = mid + 1
        } else {
            high = mid
        }
    }
    return nil
}
func insertionIndex(of value: Int, in sorted: [Int]) -> Int {
    var low = 0
    var high = sorted.count
    while low < high {
        let mid = low + (high - low) / 2
        if sorted[mid] < value {
            low = mid + 1
        } else {
            high = mid
        }
    }
    return low
}

Оба цикла держат полуинтервал и сужают его каждым шагом. В `indexOf` — ранний выход при совпадении и `nil` после цикла, в `insertionIndex` — без раннего выхода, ответ — `low`.
